465	LiaStarExtension::Subsolver& LiaStarExtension::getSubsolver(Node lambda)
466	{
467	  // Return the persistent incremental subsolver for `lambda`, creating and
468	  // seeding it on first use. It is used by the lazy strategy to enumerate the
469	  // convex cells of the predicate's satisfying region.
470	  auto it = d_subsolvers.find(lambda);
471	  if (it != d_subsolvers.end())
472	  {
473	    return it->second;
474	  }
475	  Subsolver& sub = d_subsolvers[lambda];
476	
477	  Options subOptions;
478	  // we read the model below to construct the disjunct.
479	  subOptions.write_smt().produceModels = true;
480	  sub.engine = std::make_unique<SolverEngine>(d_nm, &subOptions);
481	  sub.engine->setIsInternalSubsolver();
482	  LogicInfo info("QF_LIA");
483	  sub.engine->setLogic(info);
484	  sub.engine->setOption("incremental", "true");
485	
486	  // The base assertion is the membership predicate (with ites and negations
487	  // eliminated) conjoined with the non-negativity of the lambda's variables.
488	  Node base = LiaStarUtils::removeItesAndNots(lambda[1], &d_env);
489	  std::vector<Node> conjuncts{base};
490	  for (Node var : lambda[0])
491	  {
492	    conjuncts.push_back(d_nm->mkNode(Kind::GEQ, var, d_zero));
493	  }
494	  base =
495	      conjuncts.size() == 1 ? conjuncts[0] : d_nm->mkNode(Kind::AND, conjuncts);
496	
497	  // The lambda's bound variables appear free in `base`. A formula with free
498	  // (bound) variables cannot be asserted to a subsolver, so we replace them
499	  // with fresh free constants and remember the mapping so the disjunct built
500	  // from the model can be substituted back into bound-variable space.
501	  for (Node var : lambda[0])
502	  {
503	    if (var.getKind() == Kind::BOUND_VARIABLE)
504	    {
505	      sub.from.push_back(var);
506	      sub.to.push_back(d_nm->mkDummySkolem("liastar", var.getType()));
507	    }
508	  }
509	  if (!sub.from.empty())
510	  {
511	    base = base.substitute(
512	        sub.from.begin(), sub.from.end(), sub.to.begin(), sub.to.end());
513	  }
514	  sub.base = base;
515	  sub.engine->assertFormula(base);
516	  return sub;
517	}
