733	std::vector<std::pair<Node, Node>> LiaStarExtension::getMembershipDisjuncts(
734	    Node n, std::vector<std::pair<Node, libnormaliz::Cone<Integer>>>& cones)
735	{
736	  // Build the *membership* encoding (used only for the liastar-ext-smt debug
737	  // trace): one disjunct per (cone, module generator) stating that the vector
738	  // is a single element `g + sum_k l_k h_k` of that cone, with the multipliers
739	  // existentially bound. The disjunction over all of these is equivalent to
740	  // `v in S` (single membership, not the star). Returns each disjunct paired
741	  // with the predicate node it came from.
742	  Node vec = n[0];
743	  size_t dimension = vec.getNumChildren();
744	  std::vector<std::pair<Node, Node>> disjunctions;
745	
746	  for (auto& pair : cones)
747	  {
748	    Node node = pair.first;
749	    libnormaliz::Cone<Integer>& cone = pair.second;
750	    for (const auto& generator : getConeGenerators(cone, dimension))
751	    {
752	      // Build the generator's membership encoding in terms of bound variables
753	      // and existentially bind them.
754	      std::vector<Node> boundVariables, conjunctions;
755	      Vector point;
756	      std::vector<Vector> rays;
757	      LiaStarUtils::getGeneratorBody(dimension,
758	                                     generator,
759	                                     cone.getHilbertBasis(),
760	                                     /*star=*/false,
761	                                     /*useSkolems=*/false,
762	                                     d_nm,
763	                                     boundVariables,
764	                                     conjunctions,
765	                                     point,
766	                                     rays);
767	
768	      // the vector equals this single element: vec[i] = point[i] + sum rays
769	      Vector sums(dimension, d_zero);
770	      for (size_t i = 0; i < dimension; i++)
771	      {
772	        sums[i] = rewrite(d_nm->mkNode(Kind::ADD, sums[i], point[i]));
773	        for (const auto& ray : rays)
774	        {
775	          sums[i] = rewrite(d_nm->mkNode(Kind::ADD, sums[i], ray[i]));
776	        }
777	      }
778	
779	      for (size_t i = 0; i < dimension; i++)
780	      {
781	        conjunctions.push_back(vec[i].eqNode(sums[i]));
782	      }
783	      Node conjunction = d_nm->mkNode(Kind::AND, conjunctions);
784	      if (boundVariables.size() > 0)
785	      {
786	        Node variables = d_nm->mkNode(Kind::BOUND_VAR_LIST, boundVariables);
787	        conjunction = d_nm->mkNode(Kind::EXISTS, variables, conjunction);
788	      }
789	      disjunctions.push_back({node, conjunction});
790	    }
791	  }
792	
793	  return disjunctions;
794	}
